    91	otError NetworkData::GetNextOnMeshPrefix(otNetworkDataIterator *aIterator,
    92	                                         uint16_t               aRloc16,
    93	                                         otBorderRouterConfig * aConfig)
    94	{
    95	    otError             error = OT_ERROR_NOT_FOUND;
    96	    NetworkDataIterator iterator(aIterator);
    97	    NetworkDataTlv *    cur = reinterpret_cast<NetworkDataTlv *>(mTlvs + iterator.GetTlvOffset());
    98	    NetworkDataTlv *    end = reinterpret_cast<NetworkDataTlv *>(mTlvs + mLength);
    99	
   100	    for (; cur < end; cur = cur->GetNext(), iterator.SetSubTlvOffset(0), iterator.SetEntryIndex(0))
   101	    {
   102	        PrefixTlv *     prefix;
   103	        NetworkDataTlv *subCur;
   104	        NetworkDataTlv *subEnd;
   105	
   106	        VerifyOrExit((cur + 1) <= end && cur->GetNext() <= end, error = OT_ERROR_PARSE);
   107	
   108	        if (cur->GetType() != NetworkDataTlv::kTypePrefix)
   109	        {
   110	            continue;
   111	        }
   112	
   113	        prefix = static_cast<PrefixTlv *>(cur);
   114	        subCur = reinterpret_cast<NetworkDataTlv *>(reinterpret_cast<uint8_t *>(prefix->GetSubTlvs()) +
   115	                                                    iterator.GetSubTlvOffset());
   116	        subEnd = cur->GetNext();
   117	
   118	        for (; subCur < subEnd; subCur = subCur->GetNext(), iterator.SetEntryIndex(0))
   119	        {
   120	            BorderRouterTlv *borderRouter;
   121	
   122	            VerifyOrExit((subCur + 1) <= subEnd && subCur->GetNext() <= subEnd, error = OT_ERROR_PARSE);
   123	
   124	            if (subCur->GetType() != NetworkDataTlv::kTypeBorderRouter)
   125	            {
   126	                continue;
   127	            }
   128	
   129	            borderRouter = static_cast<BorderRouterTlv *>(subCur);
   130	
   131	            for (uint8_t index = iterator.GetEntryIndex(); index < borderRouter->GetNumEntries(); index++)
   132	            {
   133	                if (aRloc16 == Mac::kShortAddrBroadcast || borderRouter->GetEntry(index)->GetRloc() == aRloc16)
   134	                {
   135	                    BorderRouterEntry *borderRouterEntry = borderRouter->GetEntry(index);
   136	
   137	                    memset(aConfig, 0, sizeof(*aConfig));
   138	                    memcpy(&aConfig->mPrefix.mPrefix, prefix->GetPrefix(), BitVectorBytes(prefix->GetPrefixLength()));
   139	                    aConfig->mPrefix.mLength = prefix->GetPrefixLength();
   140	                    aConfig->mPreference     = borderRouterEntry->GetPreference();
   141	                    aConfig->mPreferred      = borderRouterEntry->IsPreferred();
   142	                    aConfig->mSlaac          = borderRouterEntry->IsSlaac();
   143	                    aConfig->mDhcp           = borderRouterEntry->IsDhcp();
   144	                    aConfig->mConfigure      = borderRouterEntry->IsConfigure();
   145	                    aConfig->mDefaultRoute   = borderRouterEntry->IsDefaultRoute();
   146	                    aConfig->mOnMesh         = borderRouterEntry->IsOnMesh();
   147	                    aConfig->mStable         = borderRouter->IsStable();
   148	                    aConfig->mRloc16         = borderRouterEntry->GetRloc();
   149	
   150	                    iterator.SaveTlvOffset(cur, mTlvs);
   151	                    iterator.SaveSubTlvOffset(subCur, prefix->GetSubTlvs());
   152	                    iterator.SetEntryIndex(index + 1);
   153	
   154	                    ExitNow(error = OT_ERROR_NONE);
   155	                }
   156	            }
   157	        }
   158	    }
   159	
   160	exit:
   161	    return error;
   162	}
